// Actual main repair erase and optional direct program inside full BBT recovery.
//@category SpellboundOS
import ghidra.app.emulator.EmulatorHelper;
import com.google.gson.*;
import java.util.*;
import java.io.ByteArrayOutputStream;
public class ValidateMainNandBbtRepair extends ValidateMainNandBbtRead {
 private static final String REPAIR_CONFIG="{\"ranges\":[[1882026764,264],[1882025260,372],[1882021498,98],[1882022022,102],[1882022226,104],[1882022436,108]],\"guards\":[{\"address\":1882026764,\"size\":264,\"sha256\":\"8a570a2f281d2a04e59e741a682f9c205a3411e62165873db7276a72befd0c1c\"},{\"address\":1882025260,\"size\":372,\"sha256\":\"372f387a39dcbf57f645d6006715c118fcc9c529a7a0ee7c02f47272dc4d3b31\"},{\"address\":1882021498,\"size\":98,\"sha256\":\"817ee545a34ec66ca7d9672856f33ae340ab68c93629a096c226b6d8062de178\"},{\"address\":1882022022,\"size\":102,\"sha256\":\"3602a9be3d66e9f2afe1e5f9db0d16a224fc3a6ef21a12d20670026175c31dc2\"},{\"address\":1882022226,\"size\":104,\"sha256\":\"670b0a8b4266c349ad1d296f0e1dfefc22c6c8c471255e9d7036ee542ab2e25b\"},{\"address\":1882022436,\"size\":108,\"sha256\":\"8d430081d27870a4bb468c27d64d302582b9d01f79b2c028035e6adc7b80452a\"}]}";
 private String phase;private long phaseReturn;private int phaseCommands,eraseCalls,programCalls,eraseReads,programReads;private Long eraseResult,programResult;private ByteArrayOutputStream tx;
 private long signed(long v){return v>=0x80000000L?v-0x100000000L:v;}
 private boolean stack(long p,long n){return n>=0&&p>=0x81000000L&&p+n<=0x81001000L;}
 @Override protected void configure()throws Exception {super.configure();JsonObject p=JsonParser.parseString(REPAIR_CONFIG).getAsJsonObject();for(JsonElement item:p.getAsJsonArray("ranges"))cfg.getAsJsonArray("main_probe_ranges").add(item.deepCopy());for(JsonElement item:p.getAsJsonArray("guards"))cfg.getAsJsonArray("main_probe_guards").add(item.deepCopy());}
 @Override protected void setupProbe(EmulatorHelper e){super.setupProbe(e);if(!c.get("native_main_bbt_repair").getAsBoolean())throw new IllegalStateException("Main BBT repair scope");phase=null;phaseReturn=0;phaseCommands=eraseCalls=programCalls=eraseReads=programReads=0;eraseResult=programResult=null;tx=new ByteArrayOutputStream();}
 @Override protected boolean packetFails(boolean ready,int index){return phase!=null?c.get("repair_fault_phase").getAsString().equals(phase)&&phaseCommands==c.get(ready?"repair_ready_fail_at":"repair_done_fail_at").getAsInt():super.packetFails(ready,index);}
 @Override protected void fifoWrite(int opcode,int reg,byte[] data,int total){if(opcode!=50){super.fifoWrite(opcode,reg,data,total);return;}if(!"program".equals(phase)||reg!=0||data.length!=1&&data.length!=4||tx.size()+data.length>140||total+data.length>512)throw new IllegalStateException("Repair TX FIFO bound");tx.writeBytes(data);}
 @Override protected long fifoResponse(int opcode,int reg,int n,int at){if(phase!=null&&opcode==15&&reg==192){if(n!=1)throw new IllegalStateException("Repair status width");JsonArray a=c.getAsJsonArray(phase+"_statuses");int i=phase.equals("erase")?eraseReads++:programReads++;long value=a.get(Math.min(i,a.size()-1)).getAsLong();super.fifoResponse(opcode,reg,n,at);return value;}return super.fifoResponse(opcode,reg,n,at);}
 @Override protected boolean probeService(EmulatorHelper e,long pc)throws Exception {
  if(phase!=null&&pc==phaseReturn){long v=r(e,0);if(phase.equals("erase"))eraseResult=v;else programResult=v;actions.add("main_repair_"+phase+"_return:"+signed(v));phase=null;}
  if(pc==0x702d730cL){if(phase!=null||r(e,0)!=word(e,0x70f9bbacL+156)||r(e,1)!=1)throw new IllegalStateException("Actual repair erase arguments");phase="erase";phaseReturn=e.readRegister("ra").longValue()&0xffffffffL;phaseCommands=0;eraseCalls++;actions.add("main_repair_erase_native:"+r(e,0)+":"+word(e,0x70f9bbacL));return false;}
  if(pc==0x702d6d2cL&&c.get("native_main_bbt_program").getAsBoolean()){if(phase!=null||!stack(r(e,0),140)||r(e,1)!=word(e,0x70f9bbacL+156)*64||r(e,2)!=0||r(e,3)!=140||r(e,4)!=1)throw new IllegalStateException("Actual repair program arguments");phase="program";phaseReturn=e.readRegister("ra").longValue()&0xffffffffL;phaseCommands=0;programCalls++;actions.add("main_repair_program_native:"+r(e,1)+":140:"+word(e,0x70f9bbacL)+":"+hash(mem(e,r(e,0),140)));return false;}
  if(phase!=null){
   if(pc==0x70296c24L){phaseCommands++;long p=r(e,1);if(!stack(p,32))throw new IllegalStateException("Repair packet backing");long opcode=word(e,p+8),at=word(e,p+16),n=word(e,p+24),buffer=word(e,p+20);if(opcode==6||opcode==216||opcode==50||opcode==16){byte[] b=mem(e,p,32);if(r(e,0)!=word(e,0x70f8e6f8L)||b[0]!=1||b[1]!=0||b[2]!=1||b[4]!=1||b[28]!=(opcode==50?3:1)||b[12]!=(opcode==6?0:opcode==50?2:3))throw new IllegalStateException("Repair packet fields");if(opcode==50){if(!phase.equals("program")||n!=140||at!=0||!stack(buffer,140))throw new IllegalStateException("Repair cache load packet");}else if(n!=0||buffer!=0||at!=(opcode==6?0:word(e,0x70f9bbacL+156)*64))throw new IllegalStateException("Repair command-only packet");actions.add("probe_packet:"+opcode+":"+at+":"+n+":1");return false;}}
   if(pc==0x702b38a2L&&(r(e,3)==0x70a3154cL||r(e,3)==0x70a31364L)){actions.add("log:main_repair_"+phase+"_result:"+signed(r(e,5)));ret(e,0);return true;}
  }
  return super.probeService(e,pc);
 }
 @Override protected void probeSnapshot(EmulatorHelper e,JsonObject row){super.probeSnapshot(e,row);row.addProperty("repair_erase_calls",eraseCalls);row.addProperty("repair_program_calls",programCalls);row.addProperty("repair_erase_status_reads",eraseReads);row.addProperty("repair_program_status_reads",programReads);row.add("repair_erase_return",eraseResult==null?JsonNull.INSTANCE:new JsonPrimitive(eraseResult));row.add("repair_program_return",programResult==null?JsonNull.INSTANCE:new JsonPrimitive(programResult));row.addProperty("repair_tx_hex",HexFormat.of().formatHex(tx.toByteArray()));}
}
